func TestGettersRunAfter(t *testing.T) {
	t.Run("GetBulkSyncIDs", func(t *testing.T) {
		t.Parallel()
		// Arrange
		obj := &RunAfter{}
		var expected []string
		obj.BulkSyncIDs = expected

		// Act & Assert
		assert.Equal(t, expected, obj.GetBulkSyncIDs(), "getter should return the property value")
	})

	t.Run("GetBulkSyncIDs_NilValue", func(t *testing.T) {
		t.Parallel()
		// Arrange
		obj := &RunAfter{}
		obj.BulkSyncIDs = nil

		// Act & Assert
		assert.Nil(t, obj.GetBulkSyncIDs(), "getter should return nil when property is nil")
	})

	t.Run("GetBulkSyncIDs_NilReceiver", func(t *testing.T) {
		t.Parallel()
		var obj *RunAfter
		// Should not panic - getters should handle nil receiver gracefully
		defer func() {
			if r := recover(); r != nil {
				t.Errorf("Getter panicked on nil receiver: %v", r)
			}
		}()
		_ = obj.GetBulkSyncIDs() // Should return zero value
	})

	t.Run("GetSyncIDs", func(t *testing.T) {
		t.Parallel()
		// Arrange
		obj := &RunAfter{}
		var expected []string
		obj.SyncIDs = expected

		// Act & Assert
		assert.Equal(t, expected, obj.GetSyncIDs(), "getter should return the property value")
	})

	t.Run("GetSyncIDs_NilValue", func(t *testing.T) {
		t.Parallel()
		// Arrange
		obj := &RunAfter{}
		obj.SyncIDs = nil

		// Act & Assert
		assert.Nil(t, obj.GetSyncIDs(), "getter should return nil when property is nil")
	})

	t.Run("GetSyncIDs_NilReceiver", func(t *testing.T) {
		t.Parallel()
		var obj *RunAfter
		// Should not panic - getters should handle nil receiver gracefully
		defer func() {
			if r := recover(); r != nil {
				t.Errorf("Getter panicked on nil receiver: %v", r)
			}
		}()
		_ = obj.GetSyncIDs() // Should return zero value
	})

}

